import { openDB, read, write } from './db.js';
import { validateSchema } from './schema.js';

const $ = (s, root = document) => root.querySelector(s);
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid = () => crypto.randomUUID();
const today = () => localDate(new Date());
function localDate(d) { return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`; }
const date = d => d ? new Date(d+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'}) : 'Not set';
const stamp = d => new Date(d).toLocaleString('en-US',{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'});
const types = {papers:'Literature review',ideas:'Idea planning',bench:'Benchmark testing',algorithm:'Algorithm design',experiments:'Experiment validation',writing:'Final writing',custom:'Custom plan'};
const descriptions = {papers:'Build a reading collection. Keep the evidence, questions, and discoveries together.',ideas:'Connect hypotheses, methods, and questions on a visual thinking board.',bench:'Track evaluation datasets, baselines, reproducibility checks, and benchmark runs.',algorithm:'Keep a versioned notebook of code flow, pseudocode, and design decisions.',experiments:'Make your own experiment table. Record settings, outcomes, and what changed.',writing:'Link your manuscript, track writing steps, and record revision decisions.',custom:'Your own research step, with a flexible notebook and checklist.'};
const toolsLabel = {papers:'PAPER CARDS',ideas:'FLOW BOARD',bench:'EVALUATION LOG',algorithm:'VERSION NOTEBOOK',experiments:'EXPERIMENT TABLE',writing:'MANUSCRIPT',custom:'NOTES & CHECKLIST'};
let db, state, current, stage, tab = 'stage', search = '', filter = 'all', calendarMonth = new Date(new Date().getFullYear(),new Date().getMonth(),1), selectedNode=null;
let transientUrls = [], toastTimer;
const empty = (title, text, button='') => `<div class="empty"><div class="empty-icon">↗</div><h3>${title}</h3><p>${text}</p>${button}</div>`;
const btn = (action, text, id='', cls='') => `<button type="button" class="${cls}" data-action="${action}" ${id?`data-id="${esc(id)}"`:''}>${text}</button>`;
const tag = (s,cls='') => `<span class="tag ${cls}">${esc(s)}</span>`;
const progress = p => p.stages.length ? Math.round(p.stages.filter(s=>s.status==='done').length/p.stages.length*100) : 0;
const pending = s => s.status !== 'done';
function notify(text) { $('#toast').textContent=text; $('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4000); }
async function save(pdfChanges=[]) {
  $('#storage-status').textContent='Saving to this browser…';
  try { await write(db,state,pdfChanges);$('#storage-status').textContent='Saved on this browser · '+new Date().toLocaleTimeString('en-US',{hour:'2-digit',minute:'2-digit'}); }
  catch(e) { state=await read(db,'workspace','state') || {version:1,projects:[],papers:[],updates:[]}; current=state.projects.find(p=>p.id===current?.id);stage=current?.stages.find(s=>s.id===stage?.id);throw new Error('Could not save. Storage may be full. Export a backup before clearing any browser data.'); }
}
function log(projectId,title,body='',manual=false) { state.updates.unshift({id:uid(),projectId,title,body,manual,at:new Date().toISOString()}); }
const stageInit=(type,title=types[type],start='',due='')=>({id:uid(),type,title,start,due,status:'planned',goal:'',notes:'',nodes:[],edges:[],versions:[],checks:[],table:{columns:type==='bench'?['Benchmark / dataset','Baseline / config','Metric','Result','Reproducibility notes']:['Experiment','Config / seed','Metric','Result','Finding'],rows:[]},overleaf:''});
const linkProject = (p,s) => `#project/${p.id}${s?'/'+s.id:''}`;
function route() {
  transientUrls.forEach(URL.revokeObjectURL);transientUrls=[];search='';filter='all';selectedNode=null;
  const [page,id,sid] = location.hash.slice(1).split('/');
  current=state.projects.find(p=>p.id===id);stage=current?.stages.find(s=>s.id===sid)||current?.stages[0];tab=sid==='updates'?'updates':'stage';
  document.querySelectorAll('.bar nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+(page==='project'?'studio':page||'home')));
  render();window.scrollTo(0,0);
}
function render() {
  const page = location.hash.split('/')[0].slice(1)||'home';
  $('#content').innerHTML = `<div class="wrap">${page==='home'?home():page==='studio'?studio():page==='project'?project():page==='calendar'?calendar():page==='library'?library():empty('Page not found','Return to your workspace.','<a class="btn primary" href="#studio">Open studio →</a>')}</div>`;
  if(page==='project'&&stage?.type==='ideas') bindBoard();
}
function home() { return `<section class="hero"><div><div class="eyebrow"><span class="dot"></span>A PERSONAL AI SAFETY RESEARCH SPACE</div><h1>Good research.<br><em>A work in progress.</em></h1><p>A place to record your work in AI safety. Bring your papers, ideas, algorithms, and experiments into one considered workflow — from the first question to the final draft.</p><p lang="zh-CN" class="chart-free">记录自己的 Safety 研究进展，让每一个想法、实验和发现有迹可循。</p><div class="actions"><a href="#studio" class="btn primary large">Enter the design studio <span>↗</span></a>${btn('new-project','＋ New project','','large')}</div></div><aside class="hero-card"><div class="eyebrow">THE RESEARCH WORKFLOW / 01—06</div><h2>From a question<br>to something that matters.</h2>${Object.entries(types).filter(([k])=>k!=='custom').map(([k,v],i)=>`<div class="index-line"><span>0${i+1}</span><span>${v}</span><span>${{papers:'Collect',ideas:'Connect',bench:'Measure',algorithm:'Iterate',experiments:'Validate',writing:'Communicate'}[k]} ↗</span></div>`).join('')}<p class="annotation">YOUR PROCESS, AT YOUR PACE. FULLY CUSTOMIZABLE.</p></aside></section><div class="section-top"><h2>A home for the whole process.</h2><span class="eyebrow">THINK · MAKE · REFLECT</span></div><div class="feature-grid"><article class="feature"><div class="num">01 / Give your project a direction</div><h3>Plan with intention.</h3><p>Set your research goal, start date, and deadline. Break it into milestones that appear on your calendar.</p></article><article class="feature"><div class="num">02 / Keep the work connected</div><h3>The right tool for each step.</h3><p>Reading cards, a flow board, version notebooks, editable experiment tables, and your Overleaf manuscript.</p></article><article class="feature"><div class="num">03 / Leave a useful trail</div><h3>Notice what changed.</h3><p>A project journal and a shared paper library keep decisions, findings, and progress easy to revisit.</p></article></div><div class="note-band"><p><strong>A workspace that belongs to you.</strong><br>Your records and PDFs are stored in this browser. Export a full backup to move them to another device.</p>${btn('settings','Data & backup ↗')}</div>`; }
function stats(){const active=state.projects.filter(p=>!p.archived);return `<div class="stats"><div class="stat"><small>Active projects</small><strong>${active.length.toString().padStart(2,'0')}</strong></div><div class="stat"><small>Milestones completed</small><strong>${active.reduce((n,p)=>n+p.stages.filter(s=>s.status==='done').length,0).toString().padStart(2,'0')}</strong></div><div class="stat"><small>Papers collected</small><strong>${state.papers.length.toString().padStart(2,'0')}</strong></div><div class="stat"><small>Upcoming · next 7 days</small><strong>${events().filter(e=>e.due>=today()&&e.due<=localDate(new Date(Date.now()+7*86400000))&&!e.done).length.toString().padStart(2,'0')}</strong></div></div>`;}
function studio() { return `<div class="head-row"><div><div class="eyebrow">DESIGN STUDIO / YOUR RESEARCH, IN MOTION</div><h1>Room to do good work.</h1><p>Start with a question. Build a plan. Keep a record of what you discover.</p></div><div class="actions">${btn('demo','Explore an example')}${btn('new-project','＋ New project','','primary')}</div></div>${stats()}<div class="toolbar"><div class="filter-group"><select id="project-filter" aria-label="Project status"><option value="all">Active projects</option><option value="archived">Archived projects</option><option value="everything">All projects</option></select></div><input class="search" id="project-search" placeholder="Search projects, goals, directions…" aria-label="Search projects"></div><div class="project-grid" id="project-results">${projectCards()}</div><div class="note-band"><p><strong>Your next deadline</strong><br>${events().filter(e=>!e.done&&e.due>=today()).sort((a,b)=>a.due.localeCompare(b.due)).slice(0,1).map(e=>`${esc(e.title)} · ${date(e.due)}`).join('')||'No upcoming deadlines. Add dates to a project or milestone.'}</p><a class="btn quiet" href="#calendar">Open calendar ↗</a></div>`; }
function projectCards(){const list=state.projects.filter(p=>(filter==='everything'||(filter==='archived'?p.archived:!p.archived))&&`${p.title} ${p.goal} ${p.direction}`.toLowerCase().includes(search.toLowerCase()));return list.length?list.map(p=>`<article class="project-card"><div class="row between">${tag(p.direction||'Research',p.archived?'':'green')}${p.demo?tag('EXAMPLE'):p.due&&p.due<today()&&progress(p)<100?tag('PAST DEADLINE','orange'):tag(p.archived?'ARCHIVED':'IN PROGRESS')}</div><h3><a href="${linkProject(p)}">${esc(p.title)}</a></h3><p>${esc(p.goal||'Your research question goes here.')}</p><div class="row between"><span class="muted" style="font-size:10px">${p.stages.filter(s=>s.status==='done').length} / ${p.stages.length} milestones</span><span class="muted" style="font-size:10px">${progress(p)}%</span></div><div class="progress"><i style="width:${progress(p)}%"></i></div><div class="card-foot"><span>${p.due?'Due '+date(p.due):'No deadline'}</span><a href="${linkProject(p)}">Open project ↗</a></div></article>`).join(''):empty('Every project starts somewhere.','Create a project to plan your first milestone, or explore a clearly marked example.',btn('new-project','＋ Create a project','','primary'));}
function project(){if(!current)return empty('Project not found','This project may have been removed.','<a class="btn" href="#studio">Back to studio</a>');const p=current;return `<div class="breadcrumbs"><a href="#studio">Design studio</a><span>/</span><span>${esc(p.title)}</span></div><div class="project-summary"><div><div class="row">${tag(p.direction||'Research','green')}${p.demo?tag('EXAMPLE'):''}${p.archived?tag('ARCHIVED'):''}</div><h1>${esc(p.title)}</h1><p>${esc(p.goal)}</p><div class="actions">${btn('edit-project','Edit project')}${btn('archive',p.archived?'Unarchive':'Archive')}${btn('delete-project','Delete project','','text-btn attention')}</div></div><aside class="project-dates"><div><span class="small-label">START DATE</span><strong>${date(p.start)}</strong></div><div><span class="small-label">EXPECTED DEADLINE</span><strong>${date(p.due)}</strong></div><div><span class="small-label">PROGRESS · ${progress(p)}%</span><div class="progress"><i style="width:${progress(p)}%"></i></div><span>${p.stages.filter(s=>s.status==='done').length} of ${p.stages.length} milestones complete</span></div></aside></div><div class="workspace"><aside><div class="eyebrow" style="margin-bottom:12px">PROJECT ROADMAP</div><nav class="stage-nav" aria-label="Project milestones">${p.stages.map((s,i)=>`<a class="stage-link ${tab==='stage'&&s.id===stage?.id?'active':''}" href="${linkProject(p,s)}"><div class="row"><span class="stage-num">${s.status==='done'?'✓':String(i+1).padStart(2,'0')}</span>${esc(s.title)}</div><small>${s.due?date(s.due):'Set a sub-deadline'} · ${s.status}</small></a>`).join('')}${btn('new-stage','＋ Add milestone','','text-btn')}<a class="stage-link ${tab==='updates'?'active':''}" href="#project/${p.id}/updates"><div class="row"><span class="stage-num">↺</span>Update journal</div><small>${state.updates.filter(u=>u.projectId===p.id).length} entries</small></a></nav></aside><section class="tool-panel">${tab==='updates'?journal():stage?stageTool():empty('Build your roadmap','Add a milestone and choose a tool to get started.',btn('new-stage','＋ Add milestone','','primary'))}</section></div>`;}
function stageTool(){const s=stage;return `<div class="tool-header"><div><div class="eyebrow">${toolsLabel[s.type]}</div><h2>${esc(s.title)}</h2><p>${esc(s.goal||descriptions[s.type])}</p><div class="stage-meta"><span>${date(s.start)} → ${date(s.due)}</span><label>Status <select id="stage-status" aria-label="Milestone status">${['planned','in progress','done','blocked'].map(v=>`<option ${s.status===v?'selected':''}>${v}</option>`).join('')}</select></label></div></div><div class="actions">${btn('edit-stage','Edit plan')}${btn('delete-stage','Remove','','text-btn attention')}</div></div>${s.type==='papers'?paperTool():s.type==='ideas'?ideaTool():s.type==='algorithm'?algorithmTool():s.type==='experiments'?tableTool():s.type==='bench'?benchTool():s.type==='writing'?writingTool():customTool()}`;}
function paperTool(){return `<div class="toolbar"><p class="chart-free">PDFs are also collected in the central <a href="#library"><u>paper library ↗</u></a>.</p>${btn('new-paper','＋ Add paper','','primary')}</div><div class="paper-grid">${paperCards(state.papers.filter(p=>p.projectId===current.id&&p.stageId===stage.id))}</div>`;}
function paperCards(list){return list.length?list.map(p=>`<article class="paper-card"><div class="row between"><div class="paper-symbol">PDF</div>${tag(p.status||'To read',p.status==='Read'?'green':'')}</div><h3>${esc(p.title)}</h3><span class="muted" style="font-size:11px">${esc(p.authors||'Author not specified')}${p.year?' · '+esc(p.year):''}</span><p style="margin-top:8px;margin-bottom:0"><span class="project-chip">↳ ${esc(state.projects.find(x=>x.id===p.projectId)?.title||'Unassigned')}</span></p>${p.feelings?`<div class="reading"><span class="small-label">READING REFLECTION</span><p>${esc(p.feelings)}</p></div>`:''}${p.findings?`<div class="reading"><span class="small-label">FINDINGS & QUESTIONS</span><p>${esc(p.findings)}</p></div>`:''}<div class="actions">${p.hasPdf?btn('open-pdf','Read PDF ↗',p.id):'<span class="muted" style="font-size:10px">No PDF attached</span>'}${btn('edit-paper','Edit notes',p.id)}${btn('delete-paper','Remove',p.id,'text-btn attention')}</div></article>`).join(''):empty('A reading collection, ready to grow.','Upload your first PDF and capture how you read it: the useful parts, the doubts, and the ideas it opens up.');}
function ideaTool(){return `<div class="actions">${btn('new-node','＋ Add node','','primary')}${btn('edit-node','Edit selected')}${btn('connect','Connect nodes')}${btn('delete-node','Remove node','','text-btn attention')}${btn('export-board','Export SVG ↗')}</div><div class="board-help">Drag a card to move it. Click to select; use Edit selected for text or precise X/Y placement. Connect any two cards.</div><div class="board-scroll"><div class="board" id="idea-board"><svg viewBox="0 0 1050 620" aria-hidden="true"><defs><marker id="arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto"><path d="M0 0L10 5L0 10" fill="#6f8a5e"/></marker></defs>${edgesSVG()}</svg>${stage.nodes.map(n=>`<button class="board-node" data-node="${n.id}" style="left:${n.x}px;top:${n.y}px" aria-label="Select ${esc(n.title)}"><span class="node-handle">${esc(n.kind||'IDEA')} / ↔</span><strong>${esc(n.title)}</strong><span class="node-detail">${esc(n.detail)}</span></button>`).join('')}</div></div>${stage.nodes.length?'':'<p class="chart-free">An open canvas. Add a question, a hypothesis, a method, or an evaluation step.</p>'}<div class="connections">${stage.edges.map(e=>`<span class="connection">${esc(stage.nodes.find(n=>n.id===e.from)?.title)} → ${esc(stage.nodes.find(n=>n.id===e.to)?.title)} ${btn('delete-edge','×',e.id)}</span>`).join('')}</div>`;}
function edgesSVG(){return stage.edges.map(e=>{const a=stage.nodes.find(n=>n.id===e.from),b=stage.nodes.find(n=>n.id===e.to);if(!a||!b)return '';return `<path d="M${a.x+93} ${a.y+50} L${b.x+93} ${b.y+20}" fill="none" stroke="#6f8a5e" stroke-width="2" marker-end="url(#arrow)"/>`;}).join('');}
function algorithmTool(){const v=stage.versions.find(v=>v.id===stage.activeVersion)||stage.versions.at(-1);return `<div class="toolbar"><p class="chart-free">A new version copies the current notebook. Earlier versions stay available.</p>${btn('new-version','＋ New version','','primary')}</div>${v?`<div class="version-layout"><aside class="version-list">${stage.versions.map(x=>`<button data-action="select-version" data-id="${x.id}" class="${x.id===v.id?'active':''}">${esc(x.name)}<small>${stamp(x.at)}</small></button>`).join('')}</aside><form class="notebook" id="version-form"><label>Version name<input name="name" value="${esc(v.name)}" required maxlength="100"></label><label>Code flow / pseudocode<textarea name="code" class="code" spellcheck="false">${esc(v.code)}</textarea></label><label>Reasoning, assumptions & changes<textarea name="notes">${esc(v.notes)}</textarea></label><div class="actions"><button class="primary" type="submit">Save notebook</button>${btn('download-code','Download .txt ↗',v.id)}${btn('delete-version','Delete version',v.id,'text-btn attention')}</div></form></div>`:empty('Think in versions.','Create v1 to capture the algorithm, pseudocode, assumptions, and implementation decisions.',btn('new-version','Create v1','','primary'))}`;}
function tableTool(){const t=stage.table;return `<div class="toolbar"><div class="actions">${btn('add-row','＋ Add experiment','','primary')}${btn('add-column','＋ Add column')}${btn('export-csv','Export CSV ↗')}</div><span class="chart-free">${t.rows.length} runs · edits save on leaving a cell</span></div><div class="table-scroll"><table><thead><tr>${t.columns.map((c,i)=>`<th>${esc(c)} ${btn('edit-column','✎',String(i))} ${btn('delete-column','×',String(i))}</th>`).join('')}<th>Actions</th></tr></thead><tbody>${t.rows.map(r=>`<tr>${t.columns.map((c,i)=>`<td><input data-row="${r.id}" data-col="${i}" aria-label="${esc(c)} for experiment ${esc(r.id)}" value="${esc(r.cells[i]||'')}" placeholder="—"></td>`).join('')}<td>${btn('delete-row','Remove',r.id,'text-btn attention')}</td></tr>`).join('')}</tbody></table></div>${!t.rows.length?'<div class="empty" style="margin-top:15px"><h3>Keep even the unexpected results.</h3><p>Add a run. Customize columns for your metric, dataset, seed, hardware, or observation.</p></div>':''}<p class="table-note">Tip: log seeds, model versions, and negative results to make each run reproducible.</p>`;}
function checklist(){return `<div class="toolbar"><h3 style="margin:0">Checklist</h3>${btn('add-check','＋ Add item')}</div>${stage.checks.map(c=>`<label class="check-row ${c.done?'done':''}"><input type="checkbox" data-check="${c.id}" ${c.done?'checked':''}><span>${esc(c.text)}</span>${btn('delete-check','×',c.id,'text-btn')}</label>`).join('')||'<p class="chart-free">No checklist items yet. Add your next concrete step.</p>'}`;}
function benchTool(){return `${checklist()}<div class="section-top"><h3>Evaluation runs</h3><span class="eyebrow">BASELINES · METRICS · EVIDENCE</span></div>${tableTool()}`;}
function writingTool(){const url=safeURL(stage.overleaf);return `<div class="writing-card"><div class="eyebrow">YOUR MANUSCRIPT</div><h3 style="margin-top:16px">Give the work its final form.</h3><p>Keep your Overleaf project a click away. Track each revision below.</p><div class="actions">${url?`<a class="btn primary" href="${esc(url)}" target="_blank" rel="noopener noreferrer">Open in Overleaf ↗</a>`:''}${btn('set-overleaf',url?'Edit Overleaf link':'＋ Add Overleaf link')}</div>${url?`<p style="font-size:10px;margin-top:12px;overflow-wrap:anywhere">${esc(url)}</p>`:''}</div>${checklist()}<form class="notebook" id="notes-form"><label>Writing & revision notes<textarea name="notes" placeholder="What changed in this draft? What still needs work?">${esc(stage.notes)}</textarea></label><button class="primary">Save revision notes</button></form>`;}
function customTool(){return `${checklist()}<form class="notebook" id="notes-form"><label>Research notebook<textarea name="notes" style="min-height:230px" placeholder="Plans, observations, next steps…">${esc(stage.notes)}</textarea></label><button class="primary">Save notes</button></form>`;}
function journal(){const list=state.updates.filter(u=>u.projectId===current.id);return `<div class="tool-header"><div><div class="eyebrow">THE PROJECT JOURNAL</div><h2>What changed?</h2><p>A useful trail of decisions, discoveries, blockers, and next steps.</p></div>${btn('new-update','＋ Write update','','primary')}</div><ol class="journal">${list.map(u=>`<li><div><time>${stamp(u.at)}</time><br>${tag(u.manual?'REFLECTION':'ACTIVITY')}</div><div><div class="row between"><h3>${esc(u.title)}</h3>${u.manual?`<div class="actions">${btn('edit-update','Edit',u.id,'text-btn')}${btn('delete-update','×',u.id,'text-btn')}</div>`:''}</div><p>${esc(u.body)}</p></div></li>`).join('')||'<p>No entries yet.</p>'}</ol>`;}
function events(){return state.projects.filter(p=>!p.archived).flatMap(p=>[...(p.due?[{id:p.id,project:p,title:p.title+' · project deadline',due:p.due,done:progress(p)===100}]:[]),...p.stages.filter(s=>s.due).map(s=>({id:s.id,project:p,stage:s,title:s.title,due:s.due,done:s.status==='done'}))]);}
function calendar(){const y=calendarMonth.getFullYear(),m=calendarMonth.getMonth(),first=new Date(y,m,1),offset=(first.getDay()+6)%7,ev=events().filter(e=>filter==='all'||e.project.id===filter);return `<div class="head-row"><div><div class="eyebrow">THE CALENDAR / MAKE TIME FOR THE WORK</div><h1>One milestone at a time.</h1><p>Every project and sub-deadline, brought into view. Select one to open its workspace.</p></div>${btn('export-ics','Export calendar .ics ↗')}</div><div class="toolbar"><div class="row"><button data-action="month-prev" aria-label="Previous month">←</button><h2 style="font-size:28px;margin:0 12px">${calendarMonth.toLocaleDateString('en-US',{month:'long',year:'numeric'})}</h2><button data-action="month-next" aria-label="Next month">→</button>${btn('month-today','Today')}</div><select id="calendar-filter" aria-label="Filter calendar by project"><option value="all">All active projects</option>${state.projects.filter(p=>!p.archived).map(p=>`<option value="${p.id}" ${p.id===filter?'selected':''}>${esc(p.title)}</option>`).join('')}</select></div><div class="calendar-grid">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(d=>`<div class="weekday">${d}</div>`).join('')}${Array.from({length:42},(_,i)=>{const day=new Date(y,m,1-offset+i),d=localDate(day);return `<div class="day ${day.getMonth()!==m?'outside':''} ${d===today()?'today':''}"><span class="day-number">${day.getDate()}</span>${ev.filter(e=>e.due===d).map(e=>`<a class="event ${e.done?'completed':e.due<today()?'overdue':''}" href="${linkProject(e.project,e.stage)}" title="${esc(e.project.title)}: ${esc(e.title)}">${e.done?'✓ ':''}${esc(e.title)}<br><span>${esc(e.project.title)}</span></a>`).join('')}</div>`;}).join('')}</div><div class="section-top"><h2>On the horizon</h2><span class="chart-free">Past-due milestones appear in terracotta.</span></div><div class="agenda">${ev.filter(e=>!e.done).sort((a,b)=>a.due.localeCompare(b.due)).slice(0,12).map(e=>`<a class="agenda-item" href="${linkProject(e.project,e.stage)}"><time>${date(e.due)}${e.due<today()?' · PAST DUE':''}</time><h3>${esc(e.title)}</h3><p>${esc(e.project.title)}</p></a>`).join('')||empty('Your calendar has room.','Add a deadline to a project or milestone to see it here.')}</div>`;}
function library(){return `<div class="head-row"><div><div class="eyebrow">PAPER LIBRARY / KEEP YOUR SOURCES CLOSE</div><h1>Read. Question. Connect.</h1><p>Every paper you upload, organized by project. Your reading reflections stay with the source.</p></div>${btn('library-paper','＋ Add paper','','primary')}</div><div class="toolbar"><div class="filter-group"><select id="library-filter" aria-label="Filter papers by project"><option value="all">All projects · ${state.papers.length} papers</option>${state.projects.map(p=>`<option value="${p.id}">${esc(p.title)}</option>`).join('')}</select><select id="reading-filter" aria-label="Filter by reading status"><option value="all">All reading states</option><option>To read</option><option>Reading</option><option>Read</option></select></div><input class="search" id="paper-search" placeholder="Search titles, authors, reflections…" aria-label="Search papers"></div><div class="paper-grid" id="paper-results">${paperCards(state.papers)}</div>`;}
function safeURL(s){try{const u=new URL(s);return /^https?:$/.test(u.protocol)?u.href:'';}catch{return '';}}

// Dialogs use native validation and keep the user's focus inside the active editor.
function dialog(title,body,onSubmit=null,label='Save'){const el=$('#modal');$('#modal-content').innerHTML=`<div class="modal-head"><h2>${title}</h2><button type="button" data-action="close-modal" aria-label="Close dialog">×</button></div><div class="modal-body">${onSubmit?'<form id="dialog-form">':''}${body}${onSubmit?`<div class="form-error" role="alert"></div><div class="modal-actions"><button type="button" data-action="close-modal">Cancel</button><button type="submit" class="primary">${label}</button></div></form>`:''}</div>`;if(!el.open)el.showModal();if(onSubmit)$('#dialog-form').addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget;if(!form.reportValidity())return;const submit=$('[type=submit]',form);submit.disabled=true;try{await onSubmit(new FormData(form),form);el.close();render();}catch(err){$('.form-error',form).textContent=err.message;}finally{submit.disabled=false;}});}
const field=(label,name,value='',type='text',extra='')=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const area=(label,name,value='',extra='')=>`<label class="full">${label}<textarea name="${name}" ${extra}>${esc(value)}</textarea></label>`;
function confirmAction(title,text,callback){dialog(title,`<p>${text}</p>`,callback,'Confirm');}
function validateDates(start,due,p=null){if(start&&due&&due<start)throw new Error('Deadline must be on or after the start date.');if(p&&((start&&p.start&&start<p.start)||(due&&p.due&&due>p.due)))throw new Error('Milestone dates must fit within the project start and deadline.');}
function projectDialog(edit=false){const p=edit?current:null;dialog(edit?'Edit your project.':'Start with a question.',`<p>Give the work a direction. You can refine every milestone later.</p><div class="form-grid">${field('Project title *','title',p?.title||'','text','required maxlength="160"')}${field('Research direction','direction',p?.direction||'AI Safety')}${field('Start date *','start',p?.start||today(),'date','required')}${field('Expected deadline *','due',p?.due||'','date','required')}${area('Research goal / question *','goal',p?.goal||'','required')}${!p?`<div class="full"><span class="small-label">START WITH A WORKFLOW</span>${Object.entries(types).filter(([k])=>k!=='custom').map(([k,v])=>`<label class="checkbox"><input name="types" type="checkbox" value="${k}" checked>${v}</label>`).join('')}<small>Use the default stages or uncheck any. Add custom milestones anytime.</small></div>`:''}</div>`,async f=>{validateDates(f.get('start'),f.get('due'));if(p&&p.stages.some(s=>(s.start&&s.start<f.get('start'))||(s.due&&s.due>f.get('due'))))throw new Error('Adjust milestone dates first: existing milestones fall outside these new project dates.');const values={title:f.get('title').trim(),direction:f.get('direction').trim(),start:f.get('start'),due:f.get('due'),goal:f.get('goal').trim()};if(!values.title||!values.goal)throw new Error('Please enter a title and research goal.');if(p){Object.assign(p,values);log(p.id,'Project plan updated');}else{const id=uid(),stages=f.getAll('types').map((t,i,all)=>{const a=new Date(values.start+'T12:00:00'),b=new Date(values.due+'T12:00:00'),days=Math.round((b-a)/86400000);return stageInit(t,types[t],localDate(new Date(+a+Math.floor(i*days/all.length)*86400000)),localDate(new Date(+a+Math.floor((i+1)*days/all.length)*86400000)));});const obj={id,...values,createdAt:new Date().toISOString(),archived:false,stages};state.projects.unshift(obj);log(id,'Project created',values.goal);current=obj;location.hash=linkProject(obj);}await save();notify(p?'Project updated':'Your workspace is ready');},edit?'Save project':'Create project ↗');}
function stageDialog(edit=false){const s=edit?stage:null;dialog(edit?'Refine this milestone.':'Make the next step concrete.',`<div class="form-grid">${field('Milestone title *','title',s?.title||'','text','required')}<label>Tool / stage type<select name="type" ${s?'disabled':''}>${Object.entries(types).map(([k,v])=>`<option value="${k}" ${s?.type===k?'selected':''}>${v}</option>`).join('')}</select></label>${field('Start date','start',s?.start||current.start,'date')}${field('Sub-deadline','due',s?.due||current.due,'date')}${area('Goal, deliverables & time arrangement','goal',s?.goal||'')}</div>`,async f=>{validateDates(f.get('start'),f.get('due'),current);const title=f.get('title').trim();if(!title)throw new Error('Enter a milestone title.');const x=s||stageInit(f.get('type'),title);Object.assign(x,{title,start:f.get('start'),due:f.get('due'),goal:f.get('goal')});if(!s)current.stages.push(x);log(current.id,s?'Milestone updated':'Milestone added',title);await save();location.hash=linkProject(current,x);});}
function paperDialog(id=null,fromLibrary=false){const p=state.papers.find(p=>p.id===id);if(!state.projects.length){notify('Create a project before adding papers.');return;}const pid=p?.projectId||current?.id||state.projects[0].id;dialog(p?'Read between the lines.':'Add to your reading collection.',`<p>Upload a PDF, then keep your own reflections and findings alongside it.</p><div class="form-grid">${field('Paper title *','title',p?.title||'','text','required')}${field('Authors','authors',p?.authors||'')}${field('Year','year',p?.year||'','number','min="1900" max="2200"')}<label>Reading status<select name="status">${['To read','Reading','Read'].map(v=>`<option ${p?.status===v?'selected':''}>${v}</option>`).join('')}</select></label><label>Project<select name="projectId" id="paper-project">${state.projects.map(x=>`<option value="${x.id}" ${x.id===pid?'selected':''}>${esc(x.title)}</option>`).join('')}</select></label><label>Literature milestone<select name="stageId" id="paper-stage"></select></label><label class="full">PDF ${p?.hasPdf?'(leave blank to keep existing)':'*'}<input type="file" name="pdf" accept="application/pdf,.pdf" ${!p?'required':''}><small>${p?.filename?esc(p.filename)+' · ':''}Up to 30 MB per PDF. Stored in this browser, not uploaded to GitHub.</small></label>${area('Reading reflection / 阅读感受','feelings',p?.feelings||'')}${area('Findings, questions & next ideas / 发现','findings',p?.findings||'')}</div>`,async f=>{const file=f.get('pdf');let hasPdf=p?.hasPdf||false;const changes=[];const id=p?.id||uid();if(file.size){if(file.size>30*1024*1024)throw new Error('Please use a PDF under 30 MB.');const magic=new TextDecoder().decode(await file.slice(0,1024).arrayBuffer());if(!magic.includes('%PDF-'))throw new Error('This file is not a valid PDF.');hasPdf=true;changes.push({id,blob:file});}if(!p&&!hasPdf)throw new Error('Choose a PDF file.');const projectId=f.get('projectId'),project=state.projects.find(x=>x.id===projectId);let stageId=f.get('stageId');if(!project.stages.some(x=>x.id===stageId)){const newStage=stageInit('papers');project.stages.push(newStage);stageId=newStage.id;}const title=f.get('title').trim();if(!title)throw new Error('Enter a paper title.');const data={id,projectId,stageId,title,authors:f.get('authors'),year:f.get('year'),status:f.get('status'),feelings:f.get('feelings'),findings:f.get('findings'),filename:file.size?file.name:p?.filename||'',size:file.size||p?.size||0,hasPdf,addedAt:p?.addedAt||new Date().toISOString()};if(p)Object.assign(p,data);else state.papers.unshift(data);log(projectId,p?'Reading notes updated':'Paper added',data.title);await save(changes);notify('Paper and reading notes saved');});const update=()=>{const pr=state.projects.find(x=>x.id===$('#paper-project').value);$('#paper-stage').innerHTML=pr.stages.filter(s=>s.type==='papers').map(s=>`<option value="${s.id}" ${s.id===(p?.stageId||stage?.id)?'selected':''}>${esc(s.title)}</option>`).join('')||'<option value="new">Create a literature review milestone</option>';};$('#paper-project').onchange=update;update();}
function nodeDialog(edit=false){const n=edit?stage.nodes.find(n=>n.id===selectedNode):null;if(edit&&!n){notify('Select a card on the board first.');return;}dialog(edit?'Edit this idea.':'A new connection starts here.',`<div class="form-grid">${field('Title *','title',n?.title||'','text','required maxlength="120"')}<label>Kind<select name="kind">${['QUESTION','HYPOTHESIS','METHOD','EVALUATION','FINDING','IDEA'].map(k=>`<option ${n?.kind===k?'selected':''}>${k}</option>`).join('')}</select></label>${area('Details','detail',n?.detail||'','maxlength="600"')}${field('X position','x',n?.x??30+stage.nodes.length%4*230,'number','min="0" max="850" required')}${field('Y position','y',n?.y??40+Math.floor(stage.nodes.length/4)*170,'number','min="0" max="400" required')}</div>`,async f=>{const values={title:f.get('title').trim(),kind:f.get('kind'),detail:f.get('detail'),x:+f.get('x'),y:+f.get('y')};if(!values.title)throw new Error('Enter a node title.');if(n)Object.assign(n,values);else stage.nodes.push({id:uid(),...values});log(current.id,'Idea board updated',values.title);await save();});}
function bindBoard(){let drag=null;document.querySelectorAll('[data-node]').forEach(el=>{el.addEventListener('click',()=>{selectedNode=el.dataset.node;document.querySelectorAll('[data-node]').forEach(n=>n.classList.toggle('selected',n===el));});el.addEventListener('dblclick',()=>{selectedNode=el.dataset.node;nodeDialog(true);});el.addEventListener('pointerdown',e=>{if(e.button!==0)return;const node=stage.nodes.find(n=>n.id===el.dataset.node);drag={node,dx:e.clientX,dy:e.clientY,x:node.x,y:node.y};el.setPointerCapture(e.pointerId);});el.addEventListener('pointermove',e=>{if(!drag||drag.node.id!==el.dataset.node)return;drag.node.x=Math.max(0,Math.min(850,drag.x+e.clientX-drag.dx));drag.node.y=Math.max(0,Math.min(400,drag.y+e.clientY-drag.dy));el.style.left=drag.node.x+'px';el.style.top=drag.node.y+'px';$('#idea-board svg').innerHTML='<defs><marker id="arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto"><path d="M0 0L10 5L0 10" fill="#6f8a5e"/></marker></defs>'+edgesSVG();});el.addEventListener('pointerup',async()=>{if(drag){const moved=drag.node.x!==drag.x||drag.node.y!==drag.y;drag=null;if(moved)try{await save();}catch(e){notify(e.message);render();}}});el.addEventListener('pointercancel',()=>{if(drag){drag.node.x=drag.x;drag.node.y=drag.y;drag=null;render();}});});}
function download(data,name,type='text/plain'){const url=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function csvCell(v){v=String(v??'');if(/^[=+@\-\t\r]/.test(v))v="'"+v;return '"'+v.replaceAll('"','""')+'"';}
function exportCSV(){const t=stage.table;download('\uFEFF'+[t.columns,...t.rows.map(r=>r.cells)].map(r=>r.map(csvCell).join(',')).join('\r\n'),'safetywork-experiments.csv','text/csv;charset=utf-8');}
function exportICS(){const escape=s=>s.replaceAll('\\','\\\\').replaceAll('\n','\\n').replaceAll(',','\\,').replaceAll(';','\\;');const lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//safetywork//Research calendar//EN'];events().forEach(e=>{const end=new Date(e.due+'T12:00:00');end.setDate(end.getDate()+1);lines.push('BEGIN:VEVENT','UID:'+e.id+'@safetywork','DTSTAMP:'+new Date().toISOString().replace(/[-:]/g,'').split('.')[0]+'Z','DTSTART;VALUE=DATE:'+e.due.replaceAll('-',''),'DTEND;VALUE=DATE:'+localDate(end).replaceAll('-',''),'SUMMARY:'+escape(e.title),'DESCRIPTION:'+escape(e.project.title),'END:VEVENT');});lines.push('END:VCALENDAR');download(lines.join('\r\n'),'safetywork-deadlines.ics','text/calendar');}
async function exportBackup(){notify('Preparing a complete backup, including PDFs…');const pdfs=[];for(const p of state.papers.filter(p=>p.hasPdf)){const blob=await read(db,'pdfs',p.id);if(!blob)throw new Error('Missing PDF for '+p.title+'. Backup stopped to avoid an incomplete archive.');const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(blob);});pdfs.push({id:p.id,data});}download(JSON.stringify({format:'safetywork-backup',version:1,exportedAt:new Date().toISOString(),state,pdfs}),`safetywork-backup-${today()}.json`,'application/json');notify('Complete backup downloaded. Keep it somewhere safe.');}
function validateBackup(b){if(b.format!=='safetywork-backup'||b.version!==1||!b.state||!Array.isArray(b.pdfs))throw new Error('Unsupported safetywork backup.');const s=b.state;if(s.version!==1||!['projects','papers','updates'].every(k=>Array.isArray(s[k])))throw new Error('Backup structure is invalid.');const ids=new Set();for(const p of s.projects){if(typeof p.id!=='string'||ids.has(p.id)||typeof p.title!=='string'||!Array.isArray(p.stages))throw new Error('Invalid project.');ids.add(p.id);for(const x of p.stages){if(!types[x.type]||!Array.isArray(x.nodes)||!Array.isArray(x.edges)||!Array.isArray(x.versions)||!Array.isArray(x.checks)||!x.table||!Array.isArray(x.table.columns)||!Array.isArray(x.table.rows))throw new Error('Invalid milestone data.');if(x.nodes.some(n=>typeof n.x!=='number'||typeof n.y!=='number'||!Number.isFinite(n.x)||!Number.isFinite(n.y)||n.x<0||n.x>850||n.y<0||n.y>400))throw new Error('Invalid board coordinates.');}}
  const pdfIds=new Set(b.pdfs.map(p=>p.id));for(const p of s.papers){if(!ids.has(p.projectId)||!s.projects.find(x=>x.id===p.projectId).stages.some(x=>x.id===p.stageId)||p.hasPdf&&!pdfIds.has(p.id))throw new Error('A paper or PDF is missing its project or file.');}for(const u of s.updates)if(!ids.has(u.projectId))throw new Error('An update is missing its project.');return s;}
async function importFile(file){if(file.size>300*1024*1024)throw new Error('Backup is too large for this importer (300 MB limit).');const b=JSON.parse(await file.text());validateSchema(b);validateBackup(b);const changes=[];for(const p of b.pdfs){if(typeof p.data!=='string'||!p.data.startsWith('data:')||!p.data.includes(';base64,'))throw new Error('Invalid PDF data.');const binary=atob(p.data.split(',')[1]),bytes=Uint8Array.from(binary,c=>c.charCodeAt(0));if(!new TextDecoder().decode(bytes.slice(0,1024)).includes('%PDF-'))throw new Error('Invalid PDF in backup.');changes.push({id:p.id,blob:new Blob([bytes],{type:'application/pdf'})});}const old=state;state=b.state;try{await save([...old.papers.filter(p=>p.hasPdf).map(p=>({id:p.id,remove:true})),...changes]);}catch(e){state=old;throw e;}location.hash='#studio';route();notify('Workspace restored, including PDF files.');}
async function settings(){const estimate=await navigator.storage?.estimate?.();dialog('Your work. Your data.',`<p>This is a local-first research workspace hosted on GitHub Pages. The website is public; your project records and PDFs are stored only in this browser’s IndexedDB. They are not uploaded to the public repository.</p><div class="storage-summary"><strong>${state.projects.length} projects · ${state.papers.length} papers</strong><br>${estimate?`Browser origin storage: ${(estimate.usage/1024/1024).toFixed(1)} MB used / ${(estimate.quota/1024/1024).toFixed(0)} MB available.`:'Browser storage available.'}<br>One browser at a time. Back up before clearing site data or switching devices.</div><div class="actions">${btn('export-backup','↓ Export full backup','','primary')}${btn('import-backup','↑ Restore backup')}${btn('persist-storage','Request persistent storage')}</div><ul class="help-list"><li>Backups include all projects, stages, notes, board nodes, experiments, updates, and the original PDF files. Restore replaces the workspace after confirmation.</li><li>For cross-device use, export here and restore on the other device. Automatic cloud sync and shared accounts are not part of this release.</li><li>Data belongs to this browser profile and this exact website address. A future custom domain will need a backup transfer.</li><li>Experiment cells save when you leave a cell. Notebooks have a Save button. Ctrl+S saves an open notebook.</li><li>Idea cards support dragging, text editing, connectors, and SVG export. Dates can be exported as an .ics calendar.</li></ul>`);}
async function demo(){if(state.projects.some(p=>p.demo)){location.hash=linkProject(state.projects.find(p=>p.demo));return;}const start=today(),due=localDate(new Date(Date.now()+30*86400000));const p={id:uid(),title:'Mapping reliable agent behavior',direction:'Agent safety',goal:'EXAMPLE PROJECT · Explore how task context affects agent reliability, and keep the evidence reproducible. This is sample content, not a research finding.',start,due,demo:true,archived:false,createdAt:new Date().toISOString(),stages:Object.keys(types).filter(k=>k!=='custom').map((k,i)=>stageInit(k,types[k],start,localDate(new Date(Date.now()+(i+1)*5*86400000))))};p.stages[1].nodes=[{id:uid(),title:'Research question',detail:'Which context changes matter?',kind:'QUESTION',x:40,y:80},{id:uid(),title:'Controlled evaluation',detail:'Hold the task and seeds fixed.',kind:'METHOD',x:350,y:80},{id:uid(),title:'Compare & reflect',detail:'Record failure modes, not only scores.',kind:'EVALUATION',x:660,y:80}];p.stages[1].edges=[{id:uid(),from:p.stages[1].nodes[0].id,to:p.stages[1].nodes[1].id},{id:uid(),from:p.stages[1].nodes[1].id,to:p.stages[1].nodes[2].id}];p.stages[3].versions=[{id:uid(),name:'v1 · Baseline outline',at:new Date().toISOString(),code:'for task in evaluation_set:\n    context = prepare_context(task)\n    outcome = run_agent(context, seed=42)\n    record(task, outcome)\n\n# Example pseudocode — replace with your method.',notes:'Record model version, seed, and environment before comparing results.'}];p.stages[2].checks=[{id:uid(),text:'Record dataset version and evaluation settings',done:false},{id:uid(),text:'Run a baseline and save reproducibility details',done:false}];p.stages[5].checks=[{id:uid(),text:'Write the problem statement',done:false},{id:uid(),text:'Audit claims against experimental evidence',done:false}];state.projects.unshift(p);log(p.id,'Example workspace created','Sample content to explore the tools. Delete or edit freely.');await save();location.hash=linkProject(p);}

// Interaction routing; every mutation passes through the same transactional save.
const actions={
  'close-modal':()=>$('#modal').close(), 'settings':settings,'new-project':()=>projectDialog(),'edit-project':()=>projectDialog(true),'new-stage':()=>stageDialog(),'edit-stage':()=>stageDialog(true),
  'demo':demo,'new-paper':()=>paperDialog(),'library-paper':()=>paperDialog(null,true),'edit-paper':id=>paperDialog(id),
  'archive':async()=>{current.archived=!current.archived;log(current.id,current.archived?'Project archived':'Project unarchived');await save();render();},
  'delete-project':()=>confirmAction('Delete this project?',`This removes the project, all its milestones, reading notes, attached PDFs, and update journal. Export a backup first if you want to keep a copy.`,async()=>{const id=current.id,files=state.papers.filter(p=>p.projectId===id).map(p=>({id:p.id,remove:true}));state.projects=state.projects.filter(p=>p.id!==id);state.papers=state.papers.filter(p=>p.projectId!==id);state.updates=state.updates.filter(u=>u.projectId!==id);await save(files);location.hash='#studio';}),
  'delete-stage':()=>confirmAction('Remove this milestone?','The tool data will be removed. Attached paper cards will be moved to a literature review milestone and remain in the library.',async()=>{const s=stage;current.stages=current.stages.filter(x=>x.id!==s.id);const papers=state.papers.filter(p=>p.stageId===s.id);if(papers.length){let target=current.stages.find(s=>s.type==='papers');if(!target){target=stageInit('papers');current.stages.push(target);}papers.forEach(p=>p.stageId=target.id);}log(current.id,'Milestone removed',s.title);await save();location.hash=linkProject(current);route();}),
  'delete-paper':id=>{const p=state.papers.find(p=>p.id===id);confirmAction('Remove this paper?','This removes the PDF and reading notes from both this project and the library.',async()=>{state.papers=state.papers.filter(p=>p.id!==id);log(p.projectId,'Paper removed',p.title);await save([{id,remove:true}]);});},
  'open-pdf':async id=>{const p=state.papers.find(p=>p.id===id),blob=await read(db,'pdfs',id);if(!blob)throw new Error('This PDF is missing. Attach it again through Edit notes.');const url=URL.createObjectURL(blob);transientUrls.push(url);dialog(esc(p.title),`<div class="actions" style="margin-bottom:15px"><a class="btn primary" href="${url}" target="_blank" rel="noopener">Open PDF in new tab ↗</a><a class="btn" href="${url}" download="${esc(p.filename||'paper.pdf')}">Download PDF</a></div><iframe class="pdf-frame" src="${url}" title="Paper PDF preview"></iframe>`);},
  'new-node':()=>nodeDialog(),'edit-node':()=>nodeDialog(true),
  'delete-node':()=>{if(!selectedNode)return notify('Select a card first.');confirmAction('Remove this idea?','The selected card and its connections will be removed.',async()=>{stage.nodes=stage.nodes.filter(n=>n.id!==selectedNode);stage.edges=stage.edges.filter(e=>e.from!==selectedNode&&e.to!==selectedNode);selectedNode=null;log(current.id,'Idea card removed');await save();});},
  'connect':()=>{if(stage.nodes.length<2)return notify('Add at least two nodes to connect them.');dialog('Connect the ideas.',`<div class="form-grid"><label>From<select name="from">${stage.nodes.map(n=>`<option value="${n.id}" ${selectedNode===n.id?'selected':''}>${esc(n.title)}</option>`).join('')}</select></label><label>To<select name="to">${stage.nodes.map((n,i)=>`<option value="${n.id}" ${i===1?'selected':''}>${esc(n.title)}</option>`).join('')}</select></label></div>`,async f=>{if(f.get('from')===f.get('to'))throw new Error('Choose two different nodes.');if(stage.edges.some(e=>e.from===f.get('from')&&e.to===f.get('to')))throw new Error('This connection already exists.');stage.edges.push({id:uid(),from:f.get('from'),to:f.get('to')});log(current.id,'Ideas connected');await save();});},
  'delete-edge':async id=>{stage.edges=stage.edges.filter(e=>e.id!==id);log(current.id,'Board connection removed');await save();render();},
  'export-board':()=>{const nodes=stage.nodes.map(n=>`<g transform="translate(${n.x},${n.y})"><rect width="186" height="130" rx="7" fill="#fdfdf5" stroke="#9db48e"/><text x="12" y="22" font-size="10" fill="#155b45">${esc(n.kind)}</text><text x="12" y="45" font-size="12">${esc(n.title.slice(0,25))}</text><foreignObject x="12" y="56" width="162" height="65"><div xmlns="http://www.w3.org/1999/xhtml" style="font:11px sans-serif;white-space:pre-wrap;overflow-wrap:anywhere">${esc(n.detail)}</div></foreignObject></g>`).join('');download(`<svg xmlns="http://www.w3.org/2000/svg" width="1050" height="620"><rect width="1050" height="620" fill="#f6f7f0"/>${$('#idea-board svg').innerHTML}${nodes}</svg>`,'safetywork-idea-board.svg','image/svg+xml');},
  'new-version':async()=>{const old=stage.versions.find(v=>v.id===stage.activeVersion)||stage.versions.at(-1),v={id:uid(),name:'v'+(stage.versions.length+1),at:new Date().toISOString(),code:old?.code||'',notes:old?.notes||''};stage.versions.push(v);stage.activeVersion=v.id;log(current.id,'Algorithm version created',v.name);await save();render();},
  'select-version':async id=>{stage.activeVersion=id;await save();render();},
  'delete-version':id=>confirmAction('Delete this version?','Only this saved notebook version will be removed.',async()=>{stage.versions=stage.versions.filter(v=>v.id!==id);stage.activeVersion=stage.versions.at(-1)?.id;log(current.id,'Algorithm version removed');await save();}),
  'download-code':id=>{const v=stage.versions.find(v=>v.id===id);download(v.name+'\n\n'+v.code+'\n\n'+v.notes,'safetywork-algorithm.txt');},
  'add-row':async()=>{stage.table.rows.push({id:uid(),cells:stage.table.columns.map(()=>''),at:new Date().toISOString()});log(current.id,'Experiment run added',stage.title);await save();render();},
  'add-column':()=>dialog('A new dimension.',`<div class="form-grid">${field('Column name *','name','','text','required maxlength="100"')}</div>`,async f=>{const n=f.get('name').trim();if(!n)throw new Error('Enter a column name.');stage.table.columns.push(n);stage.table.rows.forEach(r=>r.cells.push(''));log(current.id,'Experiment column added',n);await save();}),
  'edit-column':id=>dialog('Rename this column.',`<div class="form-grid">${field('Column name *','name',stage.table.columns[+id],'text','required')}</div>`,async f=>{const n=f.get('name').trim();if(!n)throw new Error('Enter a column name.');stage.table.columns[+id]=n;log(current.id,'Experiment column renamed',n);await save();}),
  'delete-column':id=>{if(stage.table.columns.length<=1)return notify('Keep at least one column.');confirmAction('Remove this column?','All cells under this column will also be removed.',async()=>{stage.table.columns.splice(+id,1);stage.table.rows.forEach(r=>r.cells.splice(+id,1));log(current.id,'Experiment column removed');await save();});},
  'delete-row':id=>confirmAction('Remove this run?','This experiment row will be permanently removed.',async()=>{stage.table.rows=stage.table.rows.filter(r=>r.id!==id);log(current.id,'Experiment run removed');await save();}),
  'export-csv':exportCSV,'export-ics':exportICS,
  'add-check':()=>dialog('One concrete next step.',`<div class="form-grid">${area('Checklist item *','text','','required')}</div>`,async f=>{if(!f.get('text').trim())throw new Error('Enter a checklist item.');stage.checks.push({id:uid(),text:f.get('text'),done:false});log(current.id,'Checklist item added',f.get('text'));await save();}),
  'delete-check':id=>confirmAction('Remove this checklist item?','The item will be removed from this milestone.',async()=>{stage.checks=stage.checks.filter(c=>c.id!==id);log(current.id,'Checklist item removed');await save();}),
  'set-overleaf':()=>dialog('Your writing desk, connected.',`<div class="form-grid">${field('Overleaf project URL *','url',stage.overleaf,'url','required placeholder="https://www.overleaf.com/project/…"')}</div>`,async f=>{const url=safeURL(f.get('url'));if(!url||!['overleaf.com','www.overleaf.com'].includes(new URL(url).hostname))throw new Error('Use an https://www.overleaf.com project or share link.');if(!url.startsWith('https:'))throw new Error('Use an HTTPS Overleaf link.');stage.overleaf=url;log(current.id,'Overleaf manuscript linked');await save();}),
  'new-update':()=>updateDialog(),'edit-update':id=>updateDialog(id),
  'delete-update':id=>confirmAction('Remove this reflection?','This written update will be removed from the journal.',async()=>{state.updates=state.updates.filter(u=>u.id!==id);await save();}),
  'month-prev':()=>{calendarMonth.setMonth(calendarMonth.getMonth()-1);render();},'month-next':()=>{calendarMonth.setMonth(calendarMonth.getMonth()+1);render();},'month-today':()=>{calendarMonth=new Date(new Date().getFullYear(),new Date().getMonth(),1);render();},
  'export-backup':exportBackup,'import-backup':()=>{confirmAction('Restore a workspace?','Restoring a backup REPLACES all current records and PDFs. Export a backup first if you want to keep this workspace. You will choose the backup file next.',()=>{$('#backup-input').value='';$('#backup-input').click();});},
  'persist-storage':async()=>{const ok=await navigator.storage?.persist?.();notify(ok?'Persistent storage granted. Keep making regular backups.':'Browser did not grant persistence. Regular backups keep your work safe.');}
};
function updateDialog(id){const u=state.updates.find(u=>u.id===id);dialog(u?'Edit your reflection.':'A moment to reflect.',`<div class="form-grid">${field('Update title *','title',u?.title||'','text','required')}${area('What changed? Findings, blockers, next steps *','body',u?.body||'','required')}</div>`,async f=>{if(!f.get('title').trim()||!f.get('body').trim())throw new Error('Enter a title and update content.');if(u)Object.assign(u,{title:f.get('title'),body:f.get('body')});else log(current.id,f.get('title'),f.get('body'),true);await save();});}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;if(b.closest('form')&&b.type==='submit')return;e.preventDefault();try{await actions[b.dataset.action]?.(b.dataset.id);}catch(err){console.error(err);notify(err.message);}});
document.addEventListener('input',e=>{if(e.target.id==='project-search'){search=e.target.value;$('#project-results').innerHTML=projectCards();}if(e.target.id==='paper-search')filterPapers();});
function filterPapers(){const q=$('#paper-search').value.toLowerCase(),pid=$('#library-filter').value,status=$('#reading-filter').value;$('#paper-results').innerHTML=paperCards(state.papers.filter(p=>(pid==='all'||p.projectId===pid)&&(status==='all'||p.status===status)&&`${p.title} ${p.authors} ${p.feelings} ${p.findings}`.toLowerCase().includes(q)));}
document.addEventListener('change',async e=>{const el=e.target;try{if(el.id==='project-filter'){filter=el.value;$('#project-results').innerHTML=projectCards();}if(['library-filter','reading-filter'].includes(el.id))filterPapers();if(el.id==='calendar-filter'){filter=el.value;render();}if(el.id==='stage-status'){stage.status=el.value;log(current.id,'Milestone status updated',stage.title+' → '+stage.status);await save();render();}if(el.dataset.check){stage.checks.find(c=>c.id===el.dataset.check).done=el.checked;log(current.id,'Checklist updated',stage.title);await save();render();}if(el.dataset.row){const r=stage.table.rows.find(r=>r.id===el.dataset.row);r.cells[+el.dataset.col]=el.value;log(current.id,'Experiment result updated',stage.title+' · '+stage.table.columns[+el.dataset.col]+': '+el.value);await save();}if(el.id==='backup-input'&&el.files[0]){try{await importFile(el.files[0]);}catch(err){notify('Restore failed: '+err.message);}}}catch(err){notify(err.message);}});
document.addEventListener('submit',async e=>{if(!['version-form','notes-form'].includes(e.target.id))return;e.preventDefault();const f=new FormData(e.target);try{if(e.target.id==='version-form'){const v=stage.versions.find(v=>v.id===stage.activeVersion)||stage.versions.at(-1);Object.assign(v,{name:f.get('name').trim(),code:f.get('code'),notes:f.get('notes'),at:new Date().toISOString()});log(current.id,'Algorithm notebook saved',v.name);}else{stage.notes=f.get('notes');log(current.id,'Research notes saved',stage.title);}await save();notify('Saved to your project');}catch(err){notify(err.message);}});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key==='s'){const form=$('#version-form')||$('#notes-form');if(form){e.preventDefault();form.requestSubmit();}}});
window.addEventListener('hashchange',route);
document.addEventListener('input',async e=>{const form=e.target.closest('#version-form,#notes-form');if(!form)return;const f=new FormData(form);if(form.id==='version-form'){const v=stage.versions.find(v=>v.id===stage.activeVersion)||stage.versions.at(-1);Object.assign(v,{name:f.get('name').trim()||v.name,code:f.get('code'),notes:f.get('notes')});}else stage.notes=f.get('notes');try{await save();}catch(err){notify(err.message);}});
try { db=await openDB();state=await read(db,'workspace','state')||{version:1,projects:[],papers:[],updates:[]};await save();route(); }
catch(e){$('#content').innerHTML=`<div class="wrap">${empty('This browser could not open the workspace.','Enable browser site storage and reload. '+esc(e.message),'<button onclick="location.reload()">Reload</button>')}</div>`;}
